const input = JSON.parse(require('fs').readFileSync(0, 'utf8'));
function isPalindrome(str) {
  const lower = str.toLowerCase();
  return lower === lower.split('').reverse().join('');
}
console.log(JSON.stringify(isPalindrome(input.str)));

const input = JSON.parse(require('fs').readFileSync(0, 'utf8'));
function flattenArray(arr) {
  return arr.reduce((flat, item) => flat.concat(Array.isArray(item) ? flattenArray(item) : item), []);
}
console.log(JSON.stringify(flattenArray(input.arr)));

const input = JSON.parse(require('fs').readFileSync(0, 'utf8'));
function countVowels(str) {
  const matches = str.match(/[aeiouAEIOU]/g);
  return matches ? matches.length : 0;
}
console.log(JSON.stringify(countVowels(input.str)));

const input = JSON.parse(require('fs').readFileSync(0, 'utf8'));
function fibonacci(n) {
  if (n < 2) return n;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    [a, b] = [b, a + b];
  }
  return b;
}
console.log(JSON.stringify(fibonacci(input.n)));
